use sovereign_engine::{compare,features,predict,THRESHOLD};
use std::{fs,env,process};
fn decode(h:&str)->Result<String,String>{if h.len()%2!=0{return Err("Hex inválido".into());}let bytes=(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).map_err(|e|e.to_string())).collect::<Result<Vec<_>,_>>()?;String::from_utf8(bytes).map_err(|e|e.to_string())}
fn run()->Result<(),String>{let args:Vec<String>=env::args().collect();match args.get(1).map(String::as_str){
 Some("compare") if args.len()==4=>{let a=fs::read_to_string(&args[2]).map_err(|e|e.to_string())?;let b=fs::read_to_string(&args[3]).map_err(|e|e.to_string())?;let r=compare(&a,&b)?;println!("{{\"similarity\":{},\"confidence\":{},\"predicted_similar\":{},\"threshold\":{},\"feature_us\":{},\"inference_us\":{},\"total_us\":{}}}",r.similarity,r.confidence,r.predicted_similar,THRESHOLD,r.feature_us,r.inference_us,r.total_us);},
 Some("parity")|Some("bench") if args.len()==3=>{let input=fs::read_to_string(&args[2]).map_err(|e|e.to_string())?;let mut max_f=0.0f64;let mut max_p=0.0f64;let mut n=0;let mut disagreements=0;let mut errors=0;println!("index,label,expected,prediction,feature_us,inference_us,total_us");for (i,line) in input.lines().enumerate(){let c:Vec<_>=line.split('\t').collect();if c.len()!=5{return Err("TSV inválido".into());}let a=decode(c[0])?;let b=decode(c[1])?;let expected:Vec<f64>=c[2].split(',').map(|v|v.parse::<f64>().map_err(|e|e.to_string())).collect::<Result<_,_>>()?;if expected.len()!=11{return Err("Vector inválido".into());}let p:f64=c[3].parse::<f64>().map_err(|e|e.to_string())?;match (features(&a,&b),compare(&a,&b)){(Ok(f),Ok(r))=>{for (x,y) in f.iter().zip(expected){max_f=max_f.max((x-y).abs());}max_p=max_p.max((predict(&f)-p).abs());if (p>=THRESHOLD)!=r.predicted_similar{disagreements+=1;}n+=1;println!("{i},{},{p},{},{},{},{}",c[4],r.confidence,r.feature_us,r.inference_us,r.total_us);},_=>{errors+=1; eprintln!("Par {i}: entrada no admitida");}}}eprintln!("{{\"pairs\":{n},\"errors\":{errors},\"max_feature_error\":{max_f},\"max_probability_error\":{max_p},\"disagreements\":{disagreements}}}");if errors>0||max_f>1e-9||max_p>1e-8||disagreements>0{return Err("Paridad no aprobada".into());}},
 _=>return Err("Uso: sovereign-engine compare original.py comparacion.py | parity results/parity.tsv | bench results/parity.tsv".into())}Ok(())}
fn main(){if let Err(e)=run(){eprintln!("{e}");process::exit(1)}}
